'use client';
import Blackout from "@/components/UI/Blackout";

import { faClose, faNavicon, faSearch } from "@fortawesome/free-solid-svg-icons";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";

import NavigationMobile from "../../NavigationMobile";
import HeaderMobileContext from "./context";
import { useEffect, useState } from "react";
import { usePathname } from "next/navigation";
import { useTranslations } from "next-intl";
import { onBodyNoScrollable } from "@/utils/helpers/onBodyNoScrollable";

const HeaderMobile = () => {
    const t = useTranslations('mobileHeader');
    const pathname = usePathname();
    const [isNavigationOpen, setIsNavigationOpen] = useState(false);
    const [isSearchActive, setIsSearchActive] = useState(false);
    const searchButtonLabel = isSearchActive ? t('closeSearch') : t('openSearch');
    const navButtonLabel = isNavigationOpen ? t('closeMenu') : t('openMenu');

    const handlerOpenNavigation = () => {
        setIsNavigationOpen(true);
        onBodyNoScrollable(true);
    }

    const handlerCloseNavigation = () => {
        setIsNavigationOpen(false);
        onBodyNoScrollable(false);
    }

    const handleOpenSearch = () => {
        setIsSearchActive(prevState => !prevState);
        if (isSearchActive) {
            onBodyNoScrollable(false);
        } else {
            onBodyNoScrollable(true);
        }
    }

    useEffect(() => {
        setIsSearchActive(false);
    }, [pathname])

    const valueContext = {
        isNavigationOpen,
        handlerCloseNavigation
    }

    return (
        <>
            <HeaderMobileContext.Provider value={valueContext}>
                <header className="flex md:hidden w-full h-[60px] sticky top-0 left-0 z-mobile-header  bg-[rgba(77,19,109,0.9)] items-center px-4 shadow-md">
                    
                    <button className="ml-auto mr-2 text-white" aria-label={searchButtonLabel} onClick={handleOpenSearch}>
                        <FontAwesomeIcon icon={isSearchActive ? faClose : faSearch} />
                    </button>
                    <button className="ml-4 text-white" aria-label={navButtonLabel} onClick={handlerOpenNavigation}>
                        <FontAwesomeIcon icon={faNavicon} />
                    </button>
                </header>
                <NavigationMobile />
                <Blackout isActive={isNavigationOpen} onClick={handlerCloseNavigation} />
            </HeaderMobileContext.Provider>
        </>
    )
}

export default HeaderMobile;